  ('fb2a7772-1ed5-405c-93ae-2603ba3b0648'::uuid, 'ccmi-community-breakfast', 'Centenary Community Ministries'' free Sunday community-breakfast program, also offering showers to people in need. This is a nonprofit service program. Source: https://centenarycommunityministries.org/community-breakfast . Verified October 23, 2026.', 'Centenary Community Ministries'' free Sunday community-breakfast program, also offering showers to people in need.'),
  ('df539105-a31c-4cc3-8492-40b01701e5dd'::uuid, 'ccmi-community-garden', 'Community garden operated by Centenary Community Ministries, providing growing space, fresh-food access and educational opportunities. The official page describes a partnership with University of Georgia Extension. This is a nonprofit program. Source: https://centenarycommunityministries.org/ministries . Verified October 23, 2026.', 'Community garden operated by Centenary Community Ministries, providing growing space, fresh-food access and educational opportunities.'),
  ('8a63ecac-34df-4725-a190-3abc59e32598'::uuid, 'ccmi-transitional-house', 'Structured residential recovery program for men experiencing homelessness or housing insecurity, operated by Centenary Community Ministries. This is a nonprofit program, not a separate corporation. Source: https://centenarycommunityministries.org/transitional-housing-2 . Verified October 23, 2026.', 'Structured residential recovery program for men experiencing homelessness or housing insecurity, operated by Centenary Community Ministries.'),
  ('8d1b15ef-34e3-474f-b4b7-077b28dbb48a'::uuid, 'ccmi-utility-assistance', 'Centenary Community Ministries program assisting with utility payments and referrals, supported by Centenary UMC, Vineville UMC and Northminster Presbyterian Church. This is a nonprofit program. Source: https://centenarycommunityministries.org/utilityassistance . Verified October 23, 2026.', 'Centenary Community Ministries program helping households with utility payments and referrals.'),
  ('f52448a9-d58d-466c-910d-c02ac551d526'::uuid, 'centenary-community-ministries-board', 'Eight-member published board of Centenary Community Ministries. Samantha Click is president, Danielle Taylor treasurer and Walker Johnson scribe. Roster term dates are not stated. Source: https://centenarycommunityministries.org/new-page-1 . Verified October 23, 2026.', 'Governing board of Centenary Community Ministries, a Macon nonprofit providing housing and community assistance.'),
  ('9640b03e-0b2d-4d82-ae1e-830327d7795e'::uuid, 'centenary-community-ministries', 'Separate 501(c)(3) founded by Centenary United Methodist Church in 2009. Provides transitional housing, community meals, utility assistance, bicycle access and a community garden. Current official staff pages identify Rachel Paul Hartman as executive director. Source: https://centenarycommunityministries.org/ . Verified October 23, 2026.', 'Macon nonprofit providing transitional housing, community meals, utility assistance, bicycle access, and a community garden.'),
